	function injectCSS() {
		if (document.getElementById("mce-style")) { return; }
		var style = el("style", "");
		style.id = "mce-style";
		style.textContent = MB_CSS;
		(document.head || document.documentElement).appendChild(style);
	}

	function setStatus(text, cls) {
		var st = root && root.querySelector(".mce-status");
		if (!st) { return; }
		st.textContent = text;
		st.className = "mce-status" + (cls ? " " + cls : "");
	}
	/* 职责：可折叠二级分组容器 mceNewGroup（从 07a-shell.js 拆出，S1 单段预算）。
	   组头可点折叠，复用全局 data-collapsed 约定 + mbCEUiState.collapsed 持久化（key="group:"+title）。
	   第 4 参 collapsed=true 表示「无记忆时默认收起」（言灵页 A~E、全局页顶层组用它把长页收起来）；
	   缺省 false 保持向后兼容（区块内二级分组仍默认展开）。 */

	/* 读折叠态：优先记忆，无记忆按 collapsed 兜底（记忆值为 0 表示展开）。 */
	function mceReadGroupFold(gkey, collapsed) {
		var saved = (mbCEUiState && mbCEUiState.collapsed && mbCEUiState.collapsed[gkey] != null)
			? mbCEUiState.collapsed[gkey] : null;
		if (saved != null) { return Number(saved) === 0; }
		return !collapsed;
	}

	/* 切换折叠态并落记忆（箭头文案随态翻转）。 */
	function mceToggleGroupFold(body, head, gkey) {
		var willClose = body.getAttribute("data-collapsed") === "0";
		body.setAttribute("data-collapsed", willClose ? "1" : "0");
		var arrowEl = head.querySelector(".mce-group-arrow");
		if (arrowEl) { arrowEl.textContent = willClose ? "▸" : "▾"; }
		if (mbCEUiState && typeof mbCEUiSave === "function") {
			mbCEUiState.collapsed = mbCEUiState.collapsed || {};
			mbCEUiState.collapsed[gkey] = willClose ? 1 : 0;
			mbCEUiSave({ collapsed: mbCEUiState.collapsed });
		}
	}

	/* 二级分组：返回组内 body 容器（组名 + 右侧副标 + 折叠箭头）。 */
	function mceNewGroup(parent, title, sub, collapsed) {
		var g = el("div", "mce-group");
		var gkey = "group:" + String(title || "");
		var isOpen = mceReadGroupFold(gkey, collapsed);
		var head = el("div", "mce-group-h mce-group-fold-head");
		head.setAttribute("role", "button");
		head.setAttribute("tabindex", "0");
		head.title = (sub ? sub + " · " : "") + "点击展开 / 收起";
		head.appendChild(el("span", "", title));
		if (sub) { head.appendChild(el("span", "mce-group-n", sub)); }
		head.appendChild(el("span", "mce-group-arrow", isOpen ? "▾" : "▸"));
		g.appendChild(head);
		var body = el("div", "mce-group-b");
		body.setAttribute("data-collapsed", isOpen ? "0" : "1");
		g.appendChild(body);
		var onFold = function () { mceToggleGroupFold(body, head, gkey); };
		head.addEventListener("click", onFold);
		head.addEventListener("keydown", function (ev) {
			if (ev.key === "Enter" || ev.key === " " || ev.keyCode === 13 || ev.keyCode === 32) {
				ev.preventDefault();
				onFold();
			}
		});
		if (parent) { parent.appendChild(g); }
		return body;
	}
/* 职责：与外部 UI 模组共存 —— 主题 token 同步 / 断点跟随 / 按钮尺寸封回 */
	/* ============ UI 兼容层：与外部 UI 模组（DoL-Game-UI）共存 ============
	   结构门禁拆段：07a-shell.js 基线已顶到 400/400 行上限，本段承载 A2/A3 的共存逻辑。
	   先例同 01b-wrote-trim.js（01-core 加错误池后 415 行超限，同法拆出）。
	   本段五件事：① A2 按钮尺寸按类封回（全局规则 (1,3,2)，padding 带 !important）；
	   ② A3 主题变量指向主 UI token（card 走两级回退，见下方 2a）；③ A4 断点跟随 cap.layout（resize 自监听）；
	   ④ A5 动效零 JS（媒体查询 + 主 UI 属性判据）；⑤ token 兜底链本身 var(--a, var(--b, def))。
	   追加方式 MB_CSS +=，manifest 序在 07a-shell.js 之后；injectCSS() 运行时才读 MB_CSS，顺序安全。 */

	/* ---- A2（探针实测，docs\probes\run-ce-align-probe.ps1）----
	   主 UI 开按钮缩放时挂 html[data-dgu-buttons-scaled]，其规则
	     html[...buttons-scaled] :is(button,input[type=button],input[type=submit]):not(#ui-bar *):not([data-overlay=modloader] *)
	   特异性 (1,3,2)：padding 带 !important、min-height 不带。
	   → padding 必须 ID 计数 ≥2 且带 !important 才赢；min-height 任意 !important 即赢。
	   → 必须按按钮类逐条封回原值：一刀切 (padding:3px 9px;min-height:0) 会把页签(--mce-tab-h 36px)、
	     标题栏(0 7px)、网格(6px 8px)、行内(22px) 各自的尺寸语义一起压平。
	   → 前导 html[data-dgu-buttons-scaled] 保证未装主 UI 时这段零匹配（对无主 UI 用户零影响）。 */
	MB_CSS +=
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-btn{padding:3px 9px!important;min-height:0!important}" +
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-btn-grid .mce-btn{padding:6px 8px!important}" +
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-inner button{padding:3px 10px!important;min-height:0!important}" +
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-row button{padding:3px 8px!important;min-height:22px!important}" +
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-tabs button{padding:8px 6px!important;min-height:var(--mce-tab-h)!important}" +
		"html[data-dgu-buttons-scaled] #mce-root#mce-root .mce-header button{padding:0 7px!important;min-height:0!important}";

	/* ---- A3：主 UI 主题 token 跟随（路径 B 的本来目的）----
	   取证（DoL-Game-UI 4.2.0 原始源码，非二手转述）：
	     1. index.js 里 getTheme() 返回的 tokens 是【变量名映射表】不是色值：
	        Cm = {neutral:"--dgu-surface", card:"--dgu-card", ocean:"--dgu-accent", mist:"--dgu-secondary",
	              text:"--dgu-text", danger:"--dgu-danger", radius:"--dgu-radius", cardRadius:"--dgu-card-radius"}
	        → 所以只能把 CE 变量指向主 UI 的变量名，不能抄色值：抄色值要监听主题切换，且主 UI 改版即失效。
	     2. style.css 定义域（按规则块逐块提取，非按行 grep）：--dgu-accent / --dgu-secondary /
	        --dgu-panel / --dgu-radius(12px) / --dgu-card-radius(16px) 在 :root；--dgu-surface / --dgu-border 也在 :root。
	        --dgu-card **不在 :root**：全 8 处定义都在 html[data-stone-free] 与 :is(...) 窄作用域里。
	        html 层那几处可被 #mce-root 继承；主 UI 未启用时变量不存在，靠 var() 兜底链退化。
	     2a. 所以 card 必须两级回退：var(--dgu-card, var(--dgu-panel, #111))。
	        只写 var(--dgu-card, #111) 时，玩家没开 stone-free 就永远拿到 #111，卡片色与主 UI 脱节
	        （2026-11-11 复核发现并修掉的真缺陷）。三级语义链：
	          开 stone-free → --dgu-card = #272729（真卡片色）
	          未开          → 退 --dgu-panel = rgba(29,30,34,.72)
	          未装主 UI     → 再退 #111
	     2b. border 反向不要"修正"成 --dgu-border：:root 上它是 --kw-hairline = #ffffff0b（4.3% 白），
	        --mce-border 只用在 .mce-btn 边框与滚动条 hover，换成它会肉眼看不见；
	        --dgu-secondary = --sf-muted = #aaa9ad 是 :root 可达且可见的那个，mist 映射维持不变。
	     3. Api 挂载：index.js 内 `Ve.DoLGameUI.ui = i.api`，随后 dispatch "dol-ui-runtime-ready"。
	        → 主 UI 晚于 CE 加载时靠该事件补；已先加载时靠 setTimeout(0)/1200ms 兜。
	   只映射 4 个核心变量（清单 A3 口径：不试图一一对应 70 个 --mce-*）。
	   注意 CE 没有 --mce-card-bg，实际变量名是 --mce-bg-card（以源码为准，不照抄清单笔误）。 */

	var MCE_HOST_TOKEN_MAP = [
		{ mce: "--mce-accent", tok: "ocean", def: "#E3B25F" },
		{ mce: "--mce-bg-card", tok: "card", def: "var(--dgu-panel, #12151A)" },
		{ mce: "--mce-border", tok: "mist", def: "rgba(255,255,255,.16)" },
		{ mce: "--mce-radius", tok: "radius", def: "12px" }
	];
	/* v2.2.1 手动主题优先：玩家在主题选择器里点过 → 本会话不再自动跟随主 UI token。
	   快照/销毁协议对照 MapleLantern dossier-theme.js：写前快照、销毁逐项 removeProperty，
	   绝不整段覆盖 root.style（会误删拖动定位等本段无关的内联样式）。 */
	var mbCEManualTheme = false;
	function mbCEDropHostTokens() {
		try {
			var rootEl = document.getElementById("mce-root");
			if (!rootEl || !rootEl.style) { return 0; }
			var n = 0;
			for (var i = 0; i < MCE_HOST_TOKEN_MAP.length; i++) {
				var m = MCE_HOST_TOKEN_MAP[i];
				if (rootEl.style.getPropertyValue(m.mce)) {
					rootEl.style.removeProperty(m.mce);
					n++;
				}
			}
			return n;
		} catch (e) { return 0; }
	}
	function mbCEMarkManualTheme() {
		try { mbCEDropHostTokens(); } catch (e) { /* 无内联 token 时静默 */ }
		mbCEManualTheme = true;
	}

	/* 返回成功写入的条数（测试/诊断用）；任何异常吞掉并返回 0 —— CE 是常驻面板，一次抛错就白屏。
	   手动主题优先时返回 -1（与 0 区分：0=无宿主/无 token，-1=玩家已手动接管，本次跳过）。
	   写入值形如 var(--dgu-accent, #d4a73c)：主 UI 变量存在则跟随，不存在时语法上仍合法并退化到 CE 原值。 */
	function syncHostTokens() {
		try {
			if (mbCEManualTheme) { return -1; }
			var api = window.DoLGameUI && window.DoLGameUI.ui;
			if (!api || typeof api.getTheme !== "function") { return 0; }
			var theme = api.getTheme();
			var tokens = theme && theme.tokens;
			if (!tokens) { return 0; }
			var root = document.getElementById("mce-root");
			if (!root) { return 0; }
			var n = 0;
			for (var i = 0; i < MCE_HOST_TOKEN_MAP.length; i++) {
				var m = MCE_HOST_TOKEN_MAP[i];
				var name = tokens[m.tok];
				if (typeof name !== "string" || name === "") { continue; }
				root.style.setProperty(m.mce, "var(" + name + ", " + m.def + ")");
				n++;
			}
			return n;
		} catch (e) { return 0; }
	}

	function scheduleHostTokenSync() {
		try { window.addEventListener("dol-ui-runtime-ready", syncHostTokens); } catch (e1) {}
		try { setTimeout(syncHostTokens, 0); } catch (e2) {}
		try { setTimeout(syncHostTokens, 1200); } catch (e3) {}
	}
	scheduleHostTokenSync();

	/* ---- A5：动效强度跟随系统设置与主 UI 动效开关（**零 JS**，故意不读 cap.reducedMotion）----
	   取证（DoL-Game-UI 4.2.0 index.js 原文，getCapabilities 函数体）：
	     P = d("(prefers-reduced-motion: reduce)")   →  reducedMotion: P
	     b = !i && documentElement.hasAttribute("data-dol-midnight")  →  enabled: b
	     motion: b && !P && documentElement.hasAttribute("data-dgu-visualMotion")
	   即 cap.reducedMotion 只是 matchMedia 的镜像，cap.motion 还夹着 enabled。
	   → 读镜像等于多一个会过期的真相源（还得自己监听 media query 变化）；matchMedia 与
	     data-dgu-visualMotion 本来就是浏览器/主 UI 自己维护的活状态，CSS 直接吃即可。
	   两条判据：
	     ① @media (prefers-reduced-motion: reduce) —— 系统级无障碍设置，与主 UI 装不装无关；
	     ② html[data-dol-midnight]:not([data-dgu-visualMotion]) —— 主 UI 已启用但玩家关了动效开关。
	        前导 data-dol-midnight 保证未装主 UI 时零匹配（该属性是主 UI 启用的准确标志）。
	   必须逐宿主写：动画声明分散在 #mce-root.mce-open / #mce-toggle.mce-theme-starry /
	   .mce-anchor-prompt 三处；.mce-anchor-prompt 挂在 #story 首个子元素下，既不在 #mce-root 里
	   也不是 body 直属，后代选择器够不到。 */
	MB_CSS +=
		"@media (prefers-reduced-motion: reduce){" +
		"#mce-root,#mce-root *{animation:none!important;transition:none!important}" +
		"#mce-toggle{animation:none!important;transition:none!important}" +
		".mce-anchor-prompt{animation:none!important;transition:none!important}" +
		".mce-anchor-prompt *{animation:none!important;transition:none!important}" +
		"}" +
		"html[data-dol-midnight]:not([data-dgu-visualMotion]) #mce-root," +
		"html[data-dol-midnight]:not([data-dgu-visualMotion]) #mce-root *{" +
		"animation:none!important;transition:none!important}" +
		"html[data-dol-midnight]:not([data-dgu-visualMotion]) #mce-toggle," +
		"html[data-dol-midnight]:not([data-dgu-visualMotion]) .mce-anchor-prompt," +
		"html[data-dol-midnight]:not([data-dgu-visualMotion]) .mce-anchor-prompt *{" +
		"animation:none!important;transition:none!important}";

	/* ---- A4：面板宽度/断点跟随主 UI 的 cap.layout ----
	   取证（index.js 原文）：layout = innerWidth<=600 ? "mobile" : innerWidth<=899 ? "tablet" : "desktop"。
	   必须写 JS 的原因：主 UI **不把 layout 挂到 html 上**——MutationObserver 的 attributeFilter 只有
	   ["data-dol-midnight","data-dgu-visual","data-dgu-visualGlass","data-dgu-visualMotion"]。
	   所以 layout 只是 getCapabilities() 调用瞬间的快照，旋转屏幕/拖窗口不会自动更新，必须自己
	   监 resize 重算，否则面板会停在旧断点。
	   与清单原写法的差异：只在 mobile 时全屏，tablet 不动——CE 的 430px 浮动面板在 601~899px 里本来
	   够用，跟着 tablet 改几何没有收益，只多一条可变的几何来源。
	   只改几何、不复制 @media(max-width:520px) 的排版补偿：那份补偿是为**430px 面板宽**设计的
	   （07a-shell.js 注释原文"避免 84-90px 输入框 + 两个按钮挤在同一行而溢出错位"）；521~600px 全屏后
	   可用宽度 ≥521px，拥挤前提已消失。
	   → 代价：521~600px 比现状（520 才全屏）提前约 80px 全屏。这是"跟随主 UI 移动布局"的必要取舍。
	   未装主 UI 时不挂类，对无主 UI 用户零影响。 */
	var MCE_HOST_MOBILE_CLASS = "mce-host-mobile";

	MB_CSS +=
		"#mce-root.mce-host-mobile{top:0;right:0;bottom:0;left:0;width:100vw;max-width:100vw;max-height:100vh;border-radius:0;border:none}";

	function syncHostLayout() {
		try {
			var root = document.getElementById("mce-root");
			if (!root) { return 0; }
			var api = window.DoLGameUI && window.DoLGameUI.ui;
			var mobile = false;
			if (api && typeof api.getCapabilities === "function") {
				var capabilities = api.getCapabilities();
				mobile = !!(capabilities && capabilities.layout === "mobile");
			}
			if (mobile) { root.classList.add(MCE_HOST_MOBILE_CLASS); }
			else { root.classList.remove(MCE_HOST_MOBILE_CLASS); }
			return mobile ? 1 : 0;
		} catch (e) { return 0; }
	}

	/* resize 节流 150ms：getCapabilities() 内部要跑 CSS.supports() 两三次，拖动窗口时每帧调会卡。
	   抛错路径故意不动 class —— getCapabilities 抛错时保持现状，比按"非 mobile"误摘更安全。 */
	var MCE_HOST_RESIZE_TIMER = 0;
	function onHostResize() {
		try {
			if (MCE_HOST_RESIZE_TIMER) { clearTimeout(MCE_HOST_RESIZE_TIMER); }
			MCE_HOST_RESIZE_TIMER = setTimeout(function () {
				MCE_HOST_RESIZE_TIMER = 0;
				syncHostLayout();
			}, 150);
		} catch (e) {}
	}

	function scheduleHostLayoutSync() {
		try { window.addEventListener("resize", onHostResize); } catch (e1) {}
		try { window.addEventListener("dol-ui-runtime-ready", syncHostLayout); } catch (e2) {}
		try { setTimeout(syncHostLayout, 0); } catch (e3) {}
		try { setTimeout(syncHostLayout, 1200); } catch (e4) {}
	}
	scheduleHostLayoutSync();

	/* ---- v2.1.15 排版核查补丁（空壳类补齐）----
	   取证：mce-place-row / mce-line-head / mce-col / mce-kv-sep 此前在 07b / 07d / 05a3 里只当标签用、MB_CSS 从未定义
	   → 场地子入口行套用 .mce-stage 的内边距与左边框，在同一张卡片里形成「卡中卡」；二级小标题与上方卡片贴死；
	     适配器动作面板的按钮挤成一行；多组「标签+数值」并排时标签与数值归属不清。
	   07a-shell.js 已顶到 400 行门禁，按本段既定约定用 MB_CSS += 追加（07d 的 mce-place-more/-subs 已有规则，不重复）。 */
	MB_CSS +=
		".mce-stage-name{min-width:0;line-height:1.4;word-break:break-all}" +
		".mce-place-row{margin:5px 0 0;padding:4px 8px;border-left-width:2px;border-radius:var(--mce-radius-sm);background:var(--mce-bg-detail)}" +
		".mce-place-row.mce-parallel{border-left-color:var(--mce-accent);background:var(--mce-bg-sel)}" +
		".mce-line-head{margin-top:8px;padding-top:6px;border-top:1px solid var(--mce-border-dim)}" +
		".mce-line-head .mce-dot{display:none}" +
		".mce-col{display:flex;flex-direction:column;gap:var(--mce-space-sm)}" +
		".mce-statrow .mce-kv-sep{color:var(--mce-txt-star);font-size:var(--mce-fs-sm);margin:0 2px}";
/* 职责：面板外壳续 —— 外层页签分发（switchOuterTab）、页签状态持久化（mbCEUiLoad / mbCEUiSave / mbCEUiCollapsed）、主题切换 */
	/* 2026-11-22 性能：全量重绘后恢复滚动位。pane.textContent="" 的瞬间内容高度归零，
	   浏览器会把 .mce-body.scrollTop 钳到 0（在列表底部点「应用」会跳回顶部）。
	   keepTop 只由调用方在「目标 pane 激活」时提供（非激活 pane 不得动共享滚动容器）。 */
	function mceRestoreScroll(bodyEl, keepTop) {
		try {
			if (!bodyEl || !(keepTop > 0)) { return; }
			bodyEl.scrollTop = Math.min(keepTop, Math.max(0, bodyEl.scrollHeight || 0));
		} catch (e) { /* 恢复失败不影响渲染 */ }
	}
	function switchOuterTab(name) {
		var tabs = root.querySelectorAll(".mce-tabs button");
		var i;
		for (i = 0; i < tabs.length; i++) {
			tabs[i].classList.toggle("mce-active", tabs[i].getAttribute("data-tab") === name);
		}
		var panes = root.querySelectorAll(".mce-pane");
		for (i = 0; i < panes.length; i++) {
			panes[i].classList.toggle("mce-active", panes[i].getAttribute("data-pane") === name);
		}
		mbCEUiSave({ tab: name }); /* v1.8.12 持久化：记录当前页签 */
		/* 页签 → 渲染器分发表（v2.2.8 由 8 条 if 链改为查表：加页签只加一项，不再把 switchOuterTab 的
		   圈复杂度往上顶；函数引用在调用时求值，届时所有段都已加载） */
		var renders = {
			player: renderPlayerGame,
			char: renderCards,
			stage: renderStagePane,
			scenes: renderScenes,
			places: renderPlaces,
			global: renderGlobal,
			mods: renderModCheats,
			yanling: renderYanling, /* v2.0.0.006 言灵页（07i-yanling.js） */
			calendar: renderCalendar /* v2.2.8 事件日历页（07x-calendar.js） */
		};
		var fn = renders[name];
		if (typeof fn === "function") { fn(); }
	}

	/* ============ v1.8.12 面板状态持久化（localStorage：页签 / 特质搜索词 / 折叠状态 / 当前角色 / 内层页签） ============ */
	/** @type {any} */
	var mbCEUiState = { tab: "char", filter: "", collapsed: {}, curName: "", innerTab: "romance", placesTab: "direct", theme: "gold", charFilter: "", diffPreview: "0", placeOpen: {}, fx: "1", tex: "1", orn: "1" };
	var mbCEUiStateKey = "mbCE_ui_state_v1";
	var mbCEUiSavedRaw = null; /* v2.2.1 上次实际写入 localStorage 的串化值（同值跳过） */
	/* v2.2.1 UI 精修：折叠类标志逐键过滤（mceFilterFlags）——损坏/外源写入的脏键按条丢弃，
	   不整对象替换（避免一个脏键污染全组）。fx/tex/orn 为外观三开关，白名单 "1"/"0"。 */
	function mceFilterFlags(obj) {
		var out = {};
		try {
			if (!obj || typeof obj !== "object") { return out; }
			var ks = Object.keys(obj);
			for (var i = 0; i < ks.length; i++) {
				var v = obj[ks[i]];
				if (v === 1 || v === 0) { out[ks[i]] = v; }
			}
		} catch (e) { /* 脏对象 → 空组 */ }
		return out;
	}
	/* v2.2.1 外观三开关单键白名单赋值（load/save 共用；抽 helper 压函数复杂度） */
	function mceUiOptApply(src, dst, key) {
		try {
			var v = src && src[key];
			if (v === "1" || v === "0") { dst[key] = v; }
		} catch (e) { /* 脏入参 → 跳过 */ }
	}
	/* v2.0.23 四主题：黑金 gold（默认，不挂类）/ 星空蓝 starry / 赛博朋克 cyberpunk / 青瓷 jade。
	   设计参考 MapleLantern v1.1.8 src/style.css 的 amber / star / cyberpunk / jade 四套 token 原文；
	   CE 的 gold 保持不变，只新增两套并把 starry 升级到 MapleLantern 的 star 数值。
	   类名沿用 mce-theme-<name>，gold 无类（历史兼容：旧存档/旧 localStorage 只有 starry|gold）。 */
	var MCE_THEMES = ["gold", "starry", "cyberpunk", "jade"];
	function mbCEThemeValid(name) { return MCE_THEMES.indexOf(name) !== -1; }
	function mbCEUiLoad() {
		try {
			var raw = (typeof localStorage !== "undefined" && localStorage) ? localStorage.getItem(mbCEUiStateKey) : null;
			if (!raw) { return; }
			var obj = JSON.parse(raw);
			if (obj && typeof obj === "object") {
				if (typeof obj.tab === "string") { mbCEUiState.tab = obj.tab; }
				if (typeof obj.filter === "string") { mbCEUiState.filter = obj.filter; curPlayerFilter = obj.filter; }
				if (obj.collapsed && typeof obj.collapsed === "object") { mbCEUiState.collapsed = mceFilterFlags(obj.collapsed); }
				/* v1.8.12 二轮优化：记住上次操作角色与角色页内层页签（切存档/重开面板免重新找） */
				if (typeof obj.curName === "string") { mbCEUiState.curName = obj.curName; }
				if (obj.innerTab === "romance" || obj.innerTab === "transform") { mbCEUiState.innerTab = obj.innerTab; curInnerTab = obj.innerTab; }
				/* v1.9.0 场景页子页签持久化（场景直达/地点） */
				if (obj.placesTab === "stage" || obj.placesTab === "direct") { mbCEUiState.placesTab = obj.placesTab; }
				/* v1.9.29 主题与角色页搜索词持久化 */
				if (mbCEThemeValid(obj.theme)) { mbCEUiState.theme = obj.theme; } /* v2.0.23 白名单扩到四主题 */
				if (typeof obj.charFilter === "string") { mbCEUiState.charFilter = obj.charFilter; charSearch = obj.charFilter; }
				/* v2.0.7：diff 预览开关持久化（此前 mbCEUiLoad 无此分支，刷新页面后开关丢失 →
				   玩家体感「预览没啥作用」）。只有明确存过 "1"/"0" 才恢复。 */
				if (obj.diffPreview === "1" || obj.diffPreview === "0" || obj.diffPreview === "true" || obj.diffPreview === "false") {
					mbCEUiState.diffPreview = (obj.diffPreview === "1" || obj.diffPreview === "true") ? "1" : "0";
				}
				/* v2.0.16：场景直达子入口折叠状态（组 id → 1 展开 / 0 收起）。此前无此键，
				   加子入口后若不持久化，切页签或重开面板就会全部收回折叠态。 */
				if (obj.placeOpen && typeof obj.placeOpen === "object") { mbCEUiState.placeOpen = mceFilterFlags(obj.placeOpen); }
				/* v2.2.1 外观三开关持久化（fx 动效 / tex 纹理 / orn 边饰），只认 "1"/"0" */
				var optKeys = ["fx", "tex", "orn"];
				for (var oi = 0; oi < optKeys.length; oi++) { mceUiOptApply(obj, mbCEUiState, optKeys[oi]); }
			}
		} catch (e) { /* 读不到偏好 → 保留默认 UI 状态 */ }
	}
	function mbCEUiSave(partial) {
		try {
			if (partial) {
				if (typeof partial.tab === "string") { mbCEUiState.tab = partial.tab; }
				if (typeof partial.filter === "string") { mbCEUiState.filter = partial.filter; }
				if (partial.collapsed) { mbCEUiState.collapsed = partial.collapsed; }
				if (typeof partial.curName === "string") { mbCEUiState.curName = partial.curName; }
				if (partial.innerTab === "romance" || partial.innerTab === "transform") { mbCEUiState.innerTab = partial.innerTab; }
				if (partial.placesTab === "stage" || partial.placesTab === "direct") { mbCEUiState.placesTab = partial.placesTab; }
				if (mbCEThemeValid(partial.theme)) { mbCEUiState.theme = partial.theme; } /* v2.0.23 白名单扩到四主题 */
				if (typeof partial.charFilter === "string") { mbCEUiState.charFilter = partial.charFilter; }
				/* v2.0.7：diff 预览开关（"1"/"0"）与布尔入参都接受 */
				if (partial.diffPreview === "1" || partial.diffPreview === "0" || partial.diffPreview === "true" || partial.diffPreview === "false" ||
					partial.diffPreview === true || partial.diffPreview === false) {
					mbCEUiState.diffPreview = (partial.diffPreview === "1" || partial.diffPreview === "true" || partial.diffPreview === true) ? "1" : "0";
				}
				/* v2.0.16：场景直达子入口折叠状态（组 id → 1/0），与 collapsed 同款白名单合并 */
				if (partial.placeOpen && typeof partial.placeOpen === "object") { mbCEUiState.placeOpen = partial.placeOpen; }
				/* v2.2.1 外观三开关（同载入白名单） */
				var optKeys = ["fx", "tex", "orn"];
				for (var oi = 0; oi < optKeys.length; oi++) { mceUiOptApply(partial, mbCEUiState, optKeys[oi]); }
			}
			if (typeof localStorage !== "undefined" && localStorage) {
				/* v2.2.1 同值不写：17 个调用点高频触发（折叠/切页签/悬浮球拖动），
				   串化比对跳过无变化的 setItem，摊平 localStorage 写放大（P2-11）。 */
				var serialized = JSON.stringify(mbCEUiState);
				if (serialized !== mbCEUiSavedRaw) {
					mbCEUiSavedRaw = serialized;
					localStorage.setItem(mbCEUiStateKey, serialized);
				}
			}
		} catch (e) { /* 持久化失败 → 偏好仅本次会话生效，不打断面板操作 */ }
	}
	function mbCEUiCollapsed(tcat, open) {
		mbCEUiState.collapsed[tcat] = open ? 0 : 1;
		mbCEUiSave({ collapsed: mbCEUiState.collapsed });
	}

	/* ============ v2.0.23 四主题：黑金（gold）/ 星空蓝（starry）/ 赛博朋克（cyberpunk）/ 青瓷（jade） ============
	   切换只做三件事：置主题状态、按主题名挂/摘 mce-theme-* 类（三类别互斥，gold 三类全摘）、
	   把主题名写到 documentElement 的 data-mce-theme（按压涟漪环挂在 body 层、不在 #mce-root 内，
	   拿不到 root 的变量继承，只能靠 html 属性这条通道才能让「点击特效」跟着主题换色）。
	   token 覆盖全在 07a-shell3-fx.js（MB_CSS += 追加，段序在 07a-shell.js 之后 → 同特异度后写生效），
	   所以本文件不碰 CSS，07a-shell.js 的 400 行顶格约束不受影响。 */
	var MCE_THEME_CLASSES = ["mce-theme-starry", "mce-theme-cyberpunk", "mce-theme-jade"];
	function setTheme(name, silent, manual) {
		try {
			/* v2.2.1 第三参 manual：主题选择器/循环切换传 true → 摘宿主 token 并切到手动主题
			   （mbCEMarkManualTheme 在 07a-host-compat.js，段序更早 → 函数声明同作用域可用）；
			   ensureDom 的存档恢复仍走 silent（不夺手动优先权）。 */
			if (manual === true) { mbCEMarkManualTheme(); }
			var t = mbCEThemeValid(name) ? name : "gold"; /* 非法/未知一律回落 gold，不写脏值 */
			mbCETheme = t;
			var cls = t === "gold" ? "" : "mce-theme-" + t;
			var nodes = [root, toggleBtn];
			var i, j;
			for (i = 0; i < nodes.length; i++) {
				var n = nodes[i];
				if (!n || !n.classList) { continue; }
				for (j = 0; j < MCE_THEME_CLASSES.length; j++) { n.classList.remove(MCE_THEME_CLASSES[j]); }
				if (cls) { n.classList.add(cls); }
			}
			/* 确认条是独立 DOM（挂 #story 内），有自己的一份就在这里同步；没有就等它下次创建时按 getTheme() 取。
			   守卫 document：本函数在无 DOM 的实例（纯逻辑测试 / 早于 ensureDom）里也会被调，
			   直接取 document.querySelector 会抛 TypeError，被外层 catch 吞成「回落 gold」——曾让 59.42 假失败。 */
			/* 只判 document 本身在不在；不要写 document.querySelector 的存在性判断——
			   TS 认定 DOM 上该方法恒有（TS2774），且假 DOM 该抛的仍要能兜住，故用 try 而不是 && 链。 */
			var doc = (typeof document !== "undefined" && document) ? document : null;
			var box = null;
			if (doc) { try { box = doc.querySelector(".mce-anchor-prompt"); } catch (e) { box = null; } }
			if (box && box.classList) {
				for (j = 0; j < MCE_THEME_CLASSES.length; j++) { box.classList.remove(MCE_THEME_CLASSES[j]); }
				if (cls) { box.classList.add(cls); }
			}
			if (doc && doc.documentElement) {
				try { doc.documentElement.setAttribute("data-mce-theme", t); } catch (e) { /* 无 root 时忽略 */ }
			}
			if (!silent) { mbCEUiSave({ theme: t }); }
			return t;
		} catch (e) { return "gold"; }
	}
	function getTheme() { return mbCETheme; }
	/* 主题按钮循环顺序：gold → starry → cyberpunk → jade → gold。
	   顺序有讲究：黑金是默认，星空蓝是玩家最熟悉的第二态（放紧邻第一档，老玩家切一下就到）；
	   赛博朋克与青瓷是新增的强风格，排在后面不干扰日常使用。 */
	function cycleTheme() {
		var cur = mbCETheme;
		var idx = MCE_THEMES.indexOf(cur);
		var next = MCE_THEMES[(idx + 1) % MCE_THEMES.length];
		return setTheme(next, false, true);
	}

	/* ============ v1.8.12 面板内错误收集器（window error + console.error → 红点 + 堆栈 + 一键复制） ============ */
	var mbCEErrors = [];
	var mbCEErrCap = 50;
	var mbCEHookDone = false;
	var mbCEErrBtn = null;
	var mbCEErrBox = null;
	var mbCEErrRows = null;
	/* v1.8.12 三巡优化：风暴熔断状态——同源 60 秒窗口合并计数，单源 ≥20 熔断 60 秒，全局 ≥200/分钟 全熔断 30 秒。
	   切断「第三方特效层每帧 console.error → 收集器高频 DOM 写」的放大循环（DoLGameUI 等每帧刷 spotlight/glow 报错时不再卡顿）。
	   四巡优化：byKey 有界（>500 丢弃最旧一半）+ 速率桶化（每分钟两桶 O(1)，替代时间戳数组）+ 面板关闭不写 badge DOM。 */
	var mbCEFuse = { byKey: {}, curCount: 0, prevCount: 0, minIdx: -1, pushCount: 0, fuseAllUntil: 0 };
	var mbCEBadgeTimer = null;
	function mbCEInFuseAll() { return Date.now() < mbCEFuse.fuseAllUntil; }
	function mbCEFuseClean() {
		try {
			var keys = Object.keys(mbCEFuse.byKey);
			if (keys.length <= 500) { return; }
			keys.sort(function (a, b) { return mbCEFuse.byKey[a].t - mbCEFuse.byKey[b].t; });
			var drop = Math.floor(keys.length / 2);
			for (var i = 0; i < drop; i++) { delete mbCEFuse.byKey[keys[i]]; }
		} catch (e) {}
	}
	function mbCEUpdateErrBadge(force) {
		/* 面板关闭时只记数据不写 DOM（省 CPU）；open() 时 force 刷新 */
		if (!openFlag && !force) { return; }
		/* force=true（清空/打开面板等明确操作）→ 同步立即写，不节流；普通 push 200ms 节流合并 */
		if (force) {
			if (mbCEBadgeTimer) { clearTimeout(mbCEBadgeTimer); mbCEBadgeTimer = null; }
			mbCEWriteErrBadge();
			return;
		}
		if (mbCEBadgeTimer) { return; }
		mbCEBadgeTimer = setTimeout(function () {
			mbCEBadgeTimer = null;
			mbCEWriteErrBadge();
		}, 200);
	}
	function mbCEWriteErrBadge() {
		try {
			if (!mbCEErrBtn) { return; }
			var n = mbCEErrors.length;
			mbCEErrBtn.textContent = n > 99 ? "99+" : String(n);
			if (mbCEErrBtn.classList) { mbCEErrBtn.classList.toggle("mce-on", n > 0); }
			else if (mbCEErrBtn.style) { mbCEErrBtn.style.display = n > 0 ? "inline-block" : "none"; }
			mbCEErrBtn.title = "面板内错误收集：" + n + " 条（点击查看 / 一键复制）" + (mbCEInFuseAll() ? " ⚠ 高频错误已熔断" : "");
		} catch (e) {}
	}
	function mbCEFmtTime(t) {
		var d = new Date(t || Date.now());
		function p(n) { return n < 10 ? "0" + n : String(n); }
		return p(d.getHours()) + ":" + p(d.getMinutes()) + ":" + p(d.getSeconds());
	}
	function mbCEPushError(msg, src, stack) {
		try {
			var now = Date.now();
			var m = String(msg || "未知错误").slice(0, 400);
			/* 七巡/九巡：第三方噪音源归一化——DoLGameUI 特效层 4 种消息 + 其他已知第三方模组报错（DependenceChecker/
			   TweeReplacer/ReplacePatcher/ModOrderContainer），交替刷屏时各自独立成源绕过单源熔断，归一为同源后
			   命中「单源 ≥20 熔断」，不再以多源各刷十几条挤满收集器 */
			var noiseRules = [
				{ re: /^Error evaluating layer (spotlight|glow|linearGradient|flatColorOverlay) property src$/, label: "特效层(DoLGameUI)" },
				{ re: /^DependenceChecker\.check\(\) not found mod /, label: "DependenceChecker(DoLGameUI)" },
				{ re: /^\[TweeReplacer\] do_patch\(\)/, label: "TweeReplacer(第三方)" },
				{ re: /^\[ReplacePatcher\] patchInReplaceParamsItem\(\)/, label: "ReplacePatcher(Paperdoll+)" },
				{ re: /^ModOrderContainer getByNameOneWithAlias\(\) cannot find name\/alias\./, label: "ModOrderContainer(第三方)" },
				{ re: /^ModOrderContainer getByNameOne\(\) cannot find name\./, label: "ModOrderContainer(SimpleFrameworks)" }
			];
			for (var ni = 0; ni < noiseRules.length; ni++) {
				if (noiseRules[ni].re.test(m)) { m = "第三方噪音·" + noiseRules[ni].label; break; }
			}
			var s = String(src || "").slice(0, 200);
			var key = m + "|" + s;
			/* 风暴计数（60 秒窗口） */
			var st = mbCEFuse.byKey[key];
			if (!st || (now - st.t) > 60000) { st = { n: 0, t: now }; }
			st.n++;
			st.t = now;
			mbCEFuse.byKey[key] = st;
			/* 全局速率：每分钟滚动两桶 O(1) 计数（四巡：替代时间戳数组，错误风暴下内存恒定） */
			var minNow = Math.floor(now / 60000);
			if (mbCEFuse.minIdx !== minNow) {
				mbCEFuse.prevCount = mbCEFuse.curCount;
				mbCEFuse.curCount = 0;
				mbCEFuse.minIdx = minNow;
			}
			mbCEFuse.curCount++;
			if (mbCEFuse.curCount + mbCEFuse.prevCount >= 200) { mbCEFuse.fuseAllUntil = now + 30000; }
			/* 四巡：熔断计数表有界——每 64 次 push 检查一次，>500 键丢弃最旧一半（防御错误源键无限变化） */
			mbCEFuse.pushCount++;
			if (mbCEFuse.pushCount % 64 === 0) { mbCEFuseClean(); }
			/* 熔断判定：单源 ≥20 次（窗口内）或全局熔断期 → 忽略不占条目 */
			if (st.n > 20 || mbCEInFuseAll()) { mbCEUpdateErrBadge(); return; }
			/* 同源 60 秒内合并计数（×N） */
			var last = mbCEErrors.length ? mbCEErrors[mbCEErrors.length - 1] : null;
			if (last && last.msg === m && last.src === s && (now - last.t) < 60000) {
				last.n = (last.n || 1) + 1;
				last.t = now;
				mbCEUpdateErrBadge();
				return;
			}
			mbCEErrors.push({ t: now, msg: m, src: s, stack: String(stack || "").slice(0, 800), n: 1 });
			if (mbCEErrors.length > mbCEErrCap) { mbCEErrors.shift(); }
			mbCEUpdateErrBadge();
		} catch (e) {}
	}
	function mbCERenderErrBox() {
		if (!mbCEErrRows) { return; }
		mbCEErrRows.textContent = "";
		/* v1.8.12 三巡优化：熔断提示（高频第三方错误被忽略时告知用户） */
		if (mbCEInFuseAll()) {
			mbCEErrRows.appendChild(el("div", "mce-errrow mce-err-fuse", "⚠ 高频错误风暴已熔断（30 秒）：期间同类错误不再记录，避免刷屏卡顿。点击「清空」可复位。"));
		}
		if (!mbCEErrors.length) {
			mbCEErrRows.appendChild(el("div", "mce-errrow", "（无记录的错误）"));
		}
		var i;
		for (i = mbCEErrors.length - 1; i >= 0; i--) {
			var e = mbCEErrors[i];
			var row = el("div", "mce-errrow");
			row.appendChild(el("div", "mce-err-msg", "[" + mbCEFmtTime(e.t) + "] #" + (mbCEErrors.length - i) + " " + e.msg + (e.n > 1 ? " ×" + e.n : "")));
			if (e.src) { row.appendChild(el("div", "mce-err-src", e.src)); }
			if (e.stack) { row.appendChild(el("div", "mce-err-src", String(e.stack).split("\n").slice(0, 3).join(" ↲ "))); }
			mbCEErrRows.appendChild(row);
		}
	}
	function mbCEToggleErrBox() {
		if (!mbCEErrBox) { return; }
		var on = mbCEErrBox.classList.toggle("mce-on");
		if (on) { mbCERenderErrBox(); }
	}
	function mbCECopyErrors() {
		try {
			var text = mbCEErrors.map(function (e, i) { return "#" + (i + 1) + " " + e.msg + (e.n > 1 ? " ×" + e.n : "") + (e.src ? " @" + e.src : "") + (e.stack ? "\n" + e.stack : ""); }).join("\n\n");
			if (!text) { text = "（无错误记录）"; }
			if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
				navigator.clipboard.writeText(text).then(function () { setStatus("已复制 " + mbCEErrors.length + " 条错误到剪贴板", MCE_CLS.ok); }, function () { setStatus("复制失败（浏览器限制），请手动选择", MCE_CLS.err); });
			} else {
				setStatus("（共 " + mbCEErrors.length + " 条错误，详见上方列表）", "");
			}
		} catch (e) { setStatus("复制失败", MCE_CLS.err); }
	}
	function mbCEHookErrors() {
		if (mbCEHookDone) { return; }
		mbCEHookDone = true;
		try {
			if (typeof window === "undefined") { return; }
			window.addEventListener("error", function (ev) {
				try {
					var e = ev && ev.error;
					mbCEPushError(ev && ev.message ? ev.message : "未知错误",
						ev && ev.filename ? ev.filename + (ev.lineno ? ":" + ev.lineno : "") : "",
						e && e.stack ? e.stack : "");
				} catch (e2) { /* 错误池上报自身失败必须静默，避免级联二次错误 */ }
			});
			/* v1.8.12 优化：Promise 拒绝（未捕获的 async/await 异常）同样进面板 */
			if (typeof window.addEventListener === "function") {
				window.addEventListener("unhandledrejection", function (ev) {
					try {
						var r = ev && ev.reason;
						mbCEPushError("未处理的 Promise 拒绝：" + (r && r.message ? r.message : (r ? String(r) : "未知原因")),
							"unhandledrejection",
							r && r.stack ? r.stack : "");
					} catch (e2) { /* 错误池上报自身失败必须静默，避免级联二次错误 */ }
				});
			}
			if (window.console && typeof window.console.error === "function") {
				var origErr = window.console.error;
				window.console.error = function () {
					try {
						var parts = [];
						for (var i = 0; i < arguments.length; i++) {
							var a = arguments[i];
							parts.push(a && a.stack ? a.stack : String(a));
						}
						mbCEPushError(parts.join(" | "), "console.error", "");
					} catch (e2) { /* 上报失败不得阻断后续 origErr 输出 */ }
					origErr.apply(this, /** @type {any} */ (arguments));
				};
			}
		} catch (e) { /* 钩子安装失败不阻断面板加载（退化为无全局错误采集） */ }
	}

/* 职责：灯台视觉层 —— 按压涟漪 / 动效开关 / 主题选择器 */
/* 07a-shell3-fx：v2.0.21 灯台视觉层（设计参考 MapleLantern v1.1.7 src/style.css 原文）。
   为什么独立成段，而不是补进 07a-shell.js：
   ① 07a-shell.js 已顶到 tools/build_js.js 结构门禁 S1 的单段 400 行上限；另行开段，不给自己开 structure-baseline 豁免；
   ② 原有 MB_CSS 的末尾一段是 @media (max-width:520px) 窄屏适配块（v2.0.7 P5）。把特效塞在那里面，
      结果是「桌面全屏看不见涟漪、只有手机竖屏能看到」—— 属于最难复现的那类 bug，本轮已实测踩到并修掉。
   CSS 用 MB_CSS += 追加（与 07a-host-compat.js / 07d-places4.js 同一机制）；
   manifest 段序保证本段排在 07a-shell.js 之后（var MB_CSS 已初始化、el() 已可用）。 */

/* ---- 纸纹（纯 CSS 多层渐变，零贴图、零网络请求）+ 按压辉光 + 玻璃参数 ----
   :root 可以重复声明，这里追加的 7 个 token 与 07a-shell.js 里的 :root 无属性冲突。 */
MB_CSS +=
	":root{" +
	"--mce-tex-panel:radial-gradient(120% 80% at 10% 0%,rgba(227,178,95,.20),transparent 58%),radial-gradient(90% 60% at 100% 100%,rgba(198,84,73,.09),transparent 62%),radial-gradient(70% 35% at 50% 100%,rgba(120,66,28,.10),transparent 72%),repeating-linear-gradient(92deg,rgba(255,255,255,.014) 0 1px,transparent 1px 10px),repeating-linear-gradient(2deg,rgba(227,178,95,.018) 0 1px,transparent 1px 14px);" +
	"--mce-tex-body:radial-gradient(100% 70% at 50% 0%,rgba(227,178,95,.075),transparent 70%),repeating-linear-gradient(115deg,rgba(255,255,255,.010) 0 1px,transparent 1px 12px);" +
	"--mce-tex-card:linear-gradient(135deg,rgba(227,178,95,.10),transparent 58%),radial-gradient(120% 80% at 10% 0%,rgba(255,235,200,.06),transparent 60%),repeating-linear-gradient(0deg,rgba(255,255,255,.008) 0 1px,transparent 1px 11px);" +
	"--mce-press-glow:rgba(227,178,95,.50);--mce-press-ripple:rgba(255,228,180,.22);--mce-blur:20px;" +
	"--mce-shadow-panel:0 24px 64px rgba(0,0,0,.55),0 2px 8px rgba(0,0,0,.35)}" ;

/* ---- 页签激活下划线：从左生长（transform-origin:left + scaleX .2→1，0.16s） ----
   依赖 07a-shell.js 里给 .mce-tabs button 加的 position:relative 作为定位父级。 */
MB_CSS +=
	".mce-tabs button.mce-active::after{content:\"\";position:absolute;left:0;right:0;bottom:-2px;height:2px;transform-origin:left center;" +
	"background:linear-gradient(90deg,var(--mce-accent),var(--mce-press-ripple));box-shadow:0 0 10px var(--mce-press-glow);" +
	"animation:mce-tabline .16s ease both}" ;

/* ---- 玻璃 / 点击涟漪 / 呼吸 / 熔断 ----
   玻璃：@supports 双写守卫，不支持就完全不声明（否则得到「半透明但没模糊」的脏底）。
   涟漪：20px 圆环 scale .45→1.9→3.4，0.46s 灯台曲线，screen 混合只提亮不压暗；
   挂 fixed + body 顶层，是因为 CE 有三层裁剪（#mce-root overflow:hidden / .mce-body overflow-y:auto / .mce-tabs overflow-x:auto）。
   呼吸：只动 box-shadow 不动 transform —— 悬浮球要能被拖动，动 transform 会和拖拽位移打架。 */
MB_CSS +=
	"@supports ((backdrop-filter:blur(2px)) or (-webkit-backdrop-filter:blur(2px))){" +
	"#mce-root{-webkit-backdrop-filter:blur(var(--mce-blur)) saturate(1.1);backdrop-filter:blur(var(--mce-blur)) saturate(1.1)}}" +
	".mce-body{background-image:var(--mce-tex-body);background-attachment:local}" +
	".mce-group{background-image:var(--mce-tex-card)}" +
	"#mce-press-ring{position:fixed;left:0;top:0;width:20px;height:20px;border-radius:50%;border:2px solid var(--mce-press-glow);" +
	"background:transparent;box-shadow:0 0 0 1px var(--mce-press-ripple),0 0 26px var(--mce-press-glow),inset 0 0 12px var(--mce-press-ripple);" +
	"pointer-events:none;z-index:2147483001;mix-blend-mode:screen;transform:translate(-50%,-50%) scale(.45);opacity:.95;" +
	"animation:mce-press-ripple .46s cubic-bezier(.2,.8,.25,1) forwards}" +
	"@keyframes mce-press-ripple{0%{opacity:.95;transform:translate(-50%,-50%) scale(.45)}55%{opacity:.9;transform:translate(-50%,-50%) scale(1.9)}100%{opacity:0;transform:translate(-50%,-50%) scale(3.4)}}" +
	"@keyframes mce-tabline{from{transform:scaleX(.2);opacity:0}to{transform:scaleX(1);opacity:1}}" +
	"@keyframes mce-breathe{0%,100%{box-shadow:0 4px 14px rgba(0,0,0,.6),0 0 10px var(--mce-press-glow)}50%{box-shadow:0 4px 14px rgba(0,0,0,.6),0 0 22px var(--mce-press-glow)}}" +
	"#mce-toggle{animation:mce-breathe 4.2s ease-in-out infinite}" +
	"#mce-toggle:active{transform:scale(.94);box-shadow:0 0 0 4px var(--mce-press-glow),0 18px 38px rgba(0,0,0,.5)}" +
	/* 涟漪挂在 body 层，不在 #mce-root 的后代里 —— 07a-host-compat.js 那三条 animation:none 够不到它，必须自带熔断 */
	"@media (prefers-reduced-motion:reduce){#mce-press-ring{animation:none!important;opacity:0!important}}" ;

/* ---- 点击特效 JS：捕获阶段 pointerdown，只加视觉、不拦事件 ----
   熔断判据与 07a-host-compat.js 的两条严格一致（系统级 reduced-motion / 主 UI 关了 data-dgu-visualMotion）。 */
function mbCEAnimOff() {
	try {
		if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) { return true; }
		var de = document.documentElement;
		return !!(de && de.hasAttribute("data-dol-midnight") && !de.hasAttribute("data-dgu-visualMotion"));
	} catch (e) { return false; }
}

var MCE_PRESS_SEL = ".mce-btn,.mce-tabs button,.mce-card,.mce-data-card,.mce-seg-btn,.mce-chip,.mce-fold-btn,.mce-icon,.mce-anchor-go";

function mbCEPressRing(ev) {
	try {
		if (!ev || ev.button > 0) { return; }
		if (mbCEAnimOff()) { return; }
		var t = ev.target;
		if (!t || !t.closest || !t.closest(MCE_PRESS_SEL)) { return; }
		var d = el("div", "");
		d.className = "mce-press-ring";
		/* v2.2.5 修复：CSS 用 #mce-press-ring（id 选择器），此前只写 className → 涟漪元素零样式、视觉完全失效 */
		d.id = "mce-press-ring";
		d.setAttribute("aria-hidden", "true");
		d.style.left = ev.clientX + "px";
		d.style.top = ev.clientY + "px";
		(document.body || document.documentElement).appendChild(d);
		setTimeout(function () { if (d.parentNode) { d.parentNode.removeChild(d); } }, 520);
	} catch (e) {}
}

if (typeof document !== "undefined" && document && document.addEventListener) {
	document.addEventListener("pointerdown", mbCEPressRing, true);
}

/* ================================================================ v2.0.23 四主题 token
 * 数值来源：MapleLantern v1.1.8 src/style.css（本地仓库 DoL-Project\MapleLantern\src\style.css）
 *   cyberpunk  L80-L119  --ml-* 令牌 + 6 层面板纹理 / 2 层正文 / 3 层卡片
 *   jade       L121-L150 青瓷釉色 + 7 层开片纹理（112° 高光条 / 118° 对角反光 / 66°·28°·-24° 三向细纹）
 *   star       L181-L224 银河 58° 流光带 + 10 个面板星点 + 3 个正文星点 + 2 个卡片星点 + 116°/64° 双流星线
 * 落地口径（照 MapleLantern 自己写在 L1052 的原则）：
 *   「只叠加颜色、描边、静态网格与光晕；布局尺寸沿用既有规格。」
 *   于是这里只做三件事：① 重声明 --mce-* 变量（组件零改动即换肤）；② 覆盖面板/正文的字面 background-image；
 *   ③ 头部分色条走 background-size 贴片（不新增伪元素、不改 flex 排版）。
 * 为什么追加在本段末尾：MB_CSS 是字符串累加，07a-shell.js 的原有规则在前，同特异度下后写生效，
 *   所以 07a-shell.js 那 400 行顶格文件一个字都不用动。
 * ---------------------------------------------------------------- */

/* ---- 悬浮球「解锁」二字可读性（v2.1.12，社区反馈 2026-11-17） ----
 * 基础规则 #mce-toggle 的 color 走 --mce-txt-on-accent（近黑），是按"亮 accent 底"设计的；
 * 但下面几个主题把球背景换成了深色渐变（cyber #0B2330→#05070F / jade #182421→#0A1110），
 * 深字落深底，玩家看到的就是"解锁二字没了、以为又出 bug"。
 * 故主题层的 #mce-toggle 必须自带 color（亮字 + 光晕和暗投影双保险），只改变量不够。
 * starry 球中央色标 #5D74C9 对深字的近似对比约 4.8:1，仍在可读区间（玩家未反馈），维持原外观。 */

