/* 子入口过滤：返回本组真正可渲染的 {name, cn, parallel} 清单（三重判据，任一不成立即剔除）。
   parallel:true = v2.0.22 起「森林商店正门」提升为与纯商店并列的主入口行，不再只收在「更多入口」折叠里。
   copy 出去而不是直接返回原数组元素，避免调用方误改 PLACE_EXTRA_ENTRIES。 */
function mbCEListPlaceEntries(entry) {
	var out = [];
	try {
		if (!entry || !entry.group || !entry.group.id) { return out; }
		var list = mbCEPlaceList(entry.group.id); /* v2.1.4：白名单双源（4.js 已满 400 行，惠特尼家那份落在 07d-places3.js 的 MB_CE_EXTRA_MORE） */
		if (!list || !list.length || !Array.isArray(entry.items)) { return out; }
		for (var i = 0; i < list.length; i++) {
			var it = list[i] || {};
			var nm = String(it.name || "");
			if (!nm) { continue; }
			if (nm === entry.group.main) { continue; } /* 与主场景同一段 → 不重复列 */
			if (entry.items.indexOf(nm) === -1) { continue; } /* 不存在 / 被 exclude 剔除 / 被别组先占 */
			if (typeof mbCEIsUnplayableEntry === "function" && mbCEIsUnplayableEntry(nm, mbCEPassageText(nm))) { continue; }
			out.push({ name: nm, cn: String(it.cn || ""), parallel: !!it.parallel });
		}
	} catch (e) { /* 存档结构异常 → 退化为「无子入口」，不影响主场景按钮 */ }
	return out;
}

/* 子入口折叠块渲染：在主场景行之后追加「▸/▾ 更多入口（N）」开关 + 展开后的逐行直达。
   放在本段而不是 07d-places2.js，是因为 places2 已接近结构门禁 400 行上限；
   依赖 el / mbCEUiState / mbCEUiSave / renderPlaces / teleportTo 全在同作用域。 */
function mbCERenderPlaceSubs(block, entry) {
	var subs = mbCEListPlaceEntries(entry);
	if (!subs.length) { return; } /* 无可直达子入口 → 不渲染开关，不留空壳 */
	subs.filter(function (s) { return s.parallel; }).forEach(function (s) {
		var pr = el("div", "mce-stage mce-place-row mce-parallel"), phead = el("div", "mce-stage-head");
		phead.appendChild(el("span", "mce-dot", ""));
		phead.appendChild(el("span", "mce-stage-name", "正门　" + s.name + (s.cn ? "　（" + s.cn + "）" : "")));
		var pb = el("button", MCE_CLS.btn, "直达");
		pb.type = "button"; pb.title = "跳转到段落：" + s.name;
		(function (t) { pb.addEventListener("click", function () { teleportTo(t); }); })(s.name);
		phead.appendChild(pb); pr.appendChild(phead); block.appendChild(pr);
	});
	subs = subs.filter(function (s) { return !s.parallel; }); if (!subs.length) { return; } /* 只剩并列项 -> 不渲染折叠开关 */
	var gid = String(entry.group.id);
	var opened = !!(mbCEUiState && mbCEUiState.placeOpen && mbCEUiState.placeOpen[gid] === 1);
	var bMore = el("button", "mce-btn mce-place-more", (opened ? "▾ " : "▸ ") + "更多入口（" + subs.length + "）");
	bMore.type = "button";
	bMore.title = opened ? "收起本组的子场景直达按钮" : "展开本组的子场景直达按钮";
	bMore.addEventListener("click", function () {
		if (!mbCEUiState.placeOpen || typeof mbCEUiState.placeOpen !== "object") { mbCEUiState.placeOpen = {}; }
		mbCEUiState.placeOpen[gid] = (mbCEUiState.placeOpen[gid] === 1) ? 0 : 1;
		mbCEUiSave({ placeOpen: mbCEUiState.placeOpen });
		renderPlaces();
	});
	block.appendChild(bMore);
	if (!opened) { return; }
	var box = el("div", "mce-place-subs");
	subs.forEach(function (s) {
		var row = el("div", "mce-stage mce-place-row");
		var head = el("div", "mce-stage-head");
		head.appendChild(el("span", "mce-dot", ""));
		head.appendChild(el("span", "mce-stage-name", s.name + (s.cn ? "　（" + s.cn + "）" : "")));
		var btn = el("button", MCE_CLS.btn, "直达");
		btn.type = "button";
		btn.title = "跳转到段落：" + s.name;
		(function (target) {
			btn.addEventListener("click", function () { teleportTo(target); });
		})(s.name);
		head.appendChild(btn);
		row.appendChild(head);
		box.appendChild(row);
	});
	block.appendChild(box);
}

/* v2.0.17 子入口状态兜底 —— 补 v2.0.16 的漏。
   取证（原版 HTML 解码后 16,087 段落）：StoryInit 仅 355 B，只跑 <<variablesStatic>>（此时每个 $ 都是 undefined），
   新档真正的 $ 初始化入口是 Start → Start2 → <<variablesStart2>>。判据 =「段落前 6 行内做 .属性 写入的键 ∩ 新档
   初始化集合（gameStartOnly + variablesStart2）的差集」，151 条子入口实测只剩两组真缺口：1) $gwylan（Forest Gwylan
   Lure 第 3 行 <<set $gwylan.lureDistance -= 5>>，只在 Widgets Named Npcs 建壳 → undefined 上写入必 TypeError）；
   2) $pubfame（Hospital Keycard Receptionist 首屏 <<set $pubfame.hospital to {}>>，只在 SV Pub Fame Intro 建壳）。
   已复核无需兜底：$compound/$docks/$livestock/$harper_appointments 在 <<variablesStart2>> 必建；$wraith 由
   <<gameStartOnly>> 建壳；$island/$prison/$farm 由既有分支处理。一律「缺失才补、不覆盖已有进度」，字面量照抄原版。 */
function mbCEFillShapeV(dst, shape) {
	if (!dst || typeof dst !== "object" || Array.isArray(dst)) { return shape; }
	for (var k in shape) {
		if (!Object.prototype.hasOwnProperty.call(shape, k)) { continue; }
		var sv = shape[k];
		if (sv && typeof sv === "object" && !Array.isArray(sv)) {
			if (!dst[k] || typeof dst[k] !== "object" || Array.isArray(dst[k])) { dst[k] = sv; }
			else { mbCEFillShapeV(dst[k], sv); }
		} else if (dst[k] === undefined) { dst[k] = sv; }
	}
	return dst;
}

function mbCEEnsureEntryState(nm, V) {
	try {
		var n = String(nm || "");
		if (!V || typeof V !== "object") { return; }
		if (n === "Forest Gwylan Lure" || n === "Nightmare Gwylan" || n.indexOf("Gwylan ") === 0) {
			V.gwylan = mbCEFillShapeV(V.gwylan, {
				progress: 0, stage: 0, sea: 0, wary: 0, robin: 0, purged: 0,
				timer: {}, request: {}, requestCount: 0, requestDone: false,
			});
			if (V.gwylan.lureDistance === undefined) {
				/* 原版 Widgets Forest：<<set $gwylan.lureDistance to Math.clamp($forest, 15, 100)>> */
				var f = Number(V.forest);
				if (!isFinite(f)) { f = 15; }
				V.gwylan.lureDistance = (typeof Math.clamp === "function") ? Math.clamp(f, 15, 100) : Math.min(100, Math.max(15, f));
				if (V.gwylan.lureWill === undefined) { V.gwylan.lureWill = 0; }
			}
		}
		if (n === "Hospital Keycard Receptionist" || n.indexOf("Brothel ") === 0) {
			/* 原版 SV Pub Fame Intro：<<set $pubfame to {seen: [], tasksDone: []}>> */
			V.pubfame = mbCEFillShapeV(V.pubfame, { seen: [], tasksDone: [] });
		}
	} catch (e) { /* 兜底失败不阻断直达：段落自身仍按原版逻辑渲染 */ }
}

/* v2.0.16 子入口样式：折叠开关 + 展开后的缩进层级（默认收起，避免竖屏拉出上百行）。
   追加到 07a-shell.js 定义的 MB_CSS（同作用域、本段在其后执行），而不是写回 shell 段 ——
   shell 段已接近结构门禁 400 行上限，样式跟着功能走更好维护。 */
MB_CSS +=
	".mce-place-more{align-self:flex-start;margin-top:6px;font-size:var(--mce-fs-btn)}" +
	".mce-place-subs{display:flex;flex-direction:column;gap:5px;margin-top:6px;padding-left:10px;border-left:2px dashed var(--mce-border-quiet)}" +
	".mce-place-subs .mce-stage{padding:5px 8px}" +
	".mce-place-subs .mce-stage-name{font-size:var(--mce-fs-btn);font-weight:600}";

/* v2.0.22 森林商店直达兜底（本体 0.5.12.13，pid=1800 与 <<widget "forestShop-main">> 逐字核对）：
   ① 首段 <<if $tryOn.autoReset isnot false>><<tryOnReset>><</if>> —— $tryOn 缺失即 TypeError 白屏；
   ② 出口 <<link [[Stop browsing clothes|Forest Shop Entrance]]>> 只在尾部 <<elseif $tryOn.value is 0>> 分支，
      value 非 0 被判「试衣中」→ 无出口 → 触发 mbCEArrivalCheck 的 no usable links 回退。
   补原版 <<tryOnInit>>（Widgets tryOnClothes）同形轻量壳：autoReset:true 让 widget 自调 <<tryOnReset>> 建全量结构。
   全部「缺失才补」，不覆盖玩家正在进行的试衣进度。 */
function mbCETryOnShell(nm, V2) {
	if (!V2) { return false; }
	var n = String(nm || "");
	if (!(n === "Forest Shop" || n.indexOf("Forest Shop ") === 0)) { return false; }
	if (typeof V2.tryOn !== "object" || V2.tryOn === null) {
		V2.tryOn = { autoReset: true, value: 0,
			showEquip: { over_head: null, over_upper: null, over_lower: null },
			showUnderEquip: { upper: null, lower: null } };
	}
	if (typeof V2.location !== "string" || !V2.location) { V2.location = "forest_shop"; }
	if (V2.outside === undefined) { V2.outside = 0; }
	return true;
}
/* 职责：场景直达组枚举（缓存版 listPlaceGroups + 三重指纹失效） */
	/* ============ v2.1.5 场景直达组枚举（从 07d-places.js 迁出 + 加结果缓存）============
	   为什么迁出：07d-places.js 当时 399 行（结构门禁上限 400，零豁免），缓存改造需要净增行；
	   迁出后该片回落到 376 行，本片独立承载枚举与缓存。

	   性能依据（2026-11-14 实测，本体 0.5.12.13 / 16,087 段 / 24 组）：
	     node tools\_tmp_bench_places.js → listPlaceGroups 单次 133~193 ms（首次 193.3，后续均值 137.3）
	     node tools\_tmp_bench_split.js  → 其中「枚举 16,087 段构造 {name,text}」仅 4 ms（3%），
	                                       「24 组 × 16,087 段的 g.match 循环」131 ms（97%）
	   即：缓存 listAllPassages 的数组只能省 3%，必须缓存**组枚举结果**本身。

	   触发频率：listPlaceGroups 全项目只有 1 个调用点（07d-places2.js 的 renderPlacesDirect 首行），
	   但 renderPlaces（07d-places.js）有 14+ 处调用点（页签切换 / 每个直达按钮回调 / 小岛写后刷新），
	   每次都会重建整个 pane → 等于玩家每点一次地点相关按钮就付一次 137 ms 主线程阻塞。

	   失效判据（三重，全部 O(1)）：
	     ① 段落数 ps.length —— MOD 增删段落必变；
	     ② Story.size —— SugarCube 自己的段落计数（不可用时记 -1，不参与比较）；
	     ③ 首段名 / 中位段名 / 末段名 —— 段数不变但整包换内容的常见形态会被捕获；
	     ④ PLACE_GROUPS.length —— 运行时 push/splice 过组表（07d-places3.js 的 IIFE）后强制重算。
	   已知盲区：段数、Story.size、首/中/末名、组数全不变而中间段落整体替换 —— 捕获不到；
	   但 ModLoader 换包是整页重载（缓存随页面销毁），实测不存在该场景。真遇到时清空
	   mbCEPlaceGroupsCache 即可（不引入 force 参数，避免调用方滥用）。 */
	var mbCEPlaceGroupsCache = null;
	function mbCEPlaceFingerprint(ps) {
		var n = ps.length;
		if (!n) { return "0|-1"; }
		var sz = (typeof Story !== "undefined" && Story && typeof Story.size === "number") ? Story.size : -1;
		return n + "|" + sz + "|" + PLACE_GROUPS.length + "|"
			+ ps[0].name + "|" + ps[Math.floor(n / 2)].name + "|" + ps[n - 1].name;
	}
	function listPlaceGroups() {
		var ps = listAllPassages();
		var fp = mbCEPlaceFingerprint(ps);
		if (mbCEPlaceGroupsCache && mbCEPlaceGroupsCache.fp === fp) { return mbCEPlaceGroupsCache.groups; }
		var seen = {};
		var out = PLACE_GROUPS.map(function (g) {
			var items = [];
			for (var j = 0; j < ps.length; j++) {
				var n = ps[j].name;
				if (seen[n]) { continue; }
				if (!g.match(n)) { continue; }
				/* 不可安全直达的段不入组、也不占 seen —— 留给后面能匹配它的原组
				   （例：「Kylar Halloween Start」是 widget 定义段，排最前的节日组不该抢） */
				if (g.exclude && g.exclude(n, mbCEPassageText(n))) { continue; }
				seen[n] = true;
				items.push(n);
			}
			items.sort(function (a, b) {
				var am = a === g.main ? 0 : 1, bm = b === g.main ? 0 : 1;
				if (am !== bm) { return am - bm; }
				return a.toLowerCase().localeCompare(b.toLowerCase());
			});
			return { group: g, items: items };
		});
		mbCEPlaceGroupsCache = { fp: fp, groups: out };
		return out;
	}
/* 职责：场景直达续段（v2.1.10 自 07d-places.js 迁出悉尼三组 + 西里斯组 + 拆出三组子入口白名单；
   结构门禁 S1 拆段：07d-places.js / 07d-places4.js 均逼近单段上限 400 行）
   四组用 unshift 插到 PLACE_GROUPS 最前，只为一件事：sydney_defile / sydney_canteen 必须排在 sydney_temple 之前
   —— listPlaceGroups 靠 seen 先占先得，否则 sydney_temple 的 "Sydney Temple" 前缀会把 Corrupt 全系列 42 段一起
   吃进去，玩家只能在大列表里翻。四组匹配前缀互不重叠（Sydney Temple Corrupt / Sydney Canteen /
   Temple Sydney·Sydney Temple / sirris），提前判定不改变任何其他组的归属。
   艾弗里庄园（"Mansion "）与格威岚花园（gwylan / Forest Shop）有与 kylar_manor / forest_shop 的先占先得依赖，
   仍留在 07d-places.js 原位 —— 挪到最前会抢走 forest_shop 的段落，tests/forest_shop_direct.js 直接 FAIL（v2.1.10 实证）。 */
	(function () {
		var groups = [
			{ id: "sydney_defile", name: "悉尼 · 亵渎仪式（神殿夜行）", match: function (n) { return n.indexOf("Sydney Temple Corrupt") === 0; }, exclude: mbCEIsUnplayableEntry, main: "Sydney Temple Corrupt", note: "亵渎仪式 42 段：夜里潜入神殿 → 搜柜找铜钥匙 → 撬锁/破门 → 取贞操带 → 祈祷室 → Sirris 接人。前置：悉尼 corrupt、贞操带 origin=temple、rank ≥ initiate、21 点后，不满足给提示；战斗段已排除。" },
			{ id: "sydney_canteen", name: "悉尼 · 食堂线（身上写字）", match: function (n) { return n.indexOf("Sydney Canteen") === 0; }, exclude: mbCEIsUnplayableEntry, main: "Sydney Canteen Bodywriting Allow", note: "食堂线 7 段：悉尼在手臂/肩背写固定短语（Sinner / Purest Love / Lusty Sinners 等）。含写字（主）/ 拒绝 / 鼓励 / 打岔 / 介入；战斗段已排除。" },
			{ id: "sydney_temple", name: "悉尼（Sydney）· 神殿居所", match: function (n) { return n.indexOf("Temple Sydney") === 0 || n.indexOf("Sydney Temple") === 0; }, main: "Temple Sydney", note: "神殿中悉尼的房间与祭坛场景（纯/堕两线都在此）。亵渎仪式（Corrupt 全链）与食堂写字段已拆到上面两组独立直达" },
			{ id: "sirris_places", name: "西里斯（Sirris）· 学校与成人商店", match: function (n) { return /sirris/i.test(n) || n === "Sydney Ride Home" || n === "Sydney Ride Temple"; }, main: "Adult Shop Approach Sirris", note: "西里斯常驻的科学教室与成人商店，以及开车接送的车程场景（悉尼的家长）" },
		];
		for (var i = groups.length - 1; i >= 0; i--) { PLACE_GROUPS.unshift(groups[i]); }
	})();
	/* 子入口白名单续写：PLACE_EXTRA_ENTRIES 在 07d-places4.js 定义，键序不影响 items 顺序（items 直接取数组）。
	   主场景不出现在子入口里（避免同段两个按钮）；战斗中继段由 mbCEIsUnplayableEntry 自动过滤。 */
	/* v2.1.10 悉尼亵渎仪式全链子入口（按剧情顺序排列，玩家一路点下去） */
