		if (!src) { return false; }
		src = mbCEStripComments(src);
		if (src.indexOf("<<endevent") !== -1 || src.indexOf("<<badEndTrackingEnd") !== -1) { return true; }
		var tbl = mbCEWidgetEndTable();
		var reC = /<<([A-Za-z_][A-Za-z0-9_]*)/g, mm;
