			if (g && "hypnosis" in g) { delete g.hypnosis; cleared.push("$daily.gwylan.hypnosis"); }
			if (V.hypnosis_potency !== undefined) { delete V.hypnosis_potency; cleared.push("$hypnosis_potency"); }
