		"high elk": "高麋鹿",
		"crimson hound": "猩红猎犬",
		"silver fox": "银狐狸",
		"priest": "神父",
		"priestess": "修女",
		"headmaster": "校长",
		"headmistress": "女校长",
		"hunter": "猎手",
		"huntress": "女猎手",
		"businessman": "商人",
