		mountApi(); mbCEExportVcore(); mbCEExportLeaf(); mbCEExportYanlingQuick(); mbCEExportYanlingPosts(); /* v2.0.9 vcore 导出（原版档案/收藏/头衔）+ v2.1.8 枝叶变装导出 + v2.1.17 言灵补丁导出 + 2026-11-23 贴吧三键导出，均与 mountApi 同步补齐 */
		hookPassageOverride();
		hookPassageInit();
		hookPassageEnd(); /* v1.9.23：锚定触发判定（走到锚定地点交互时弹确认条） */
		hookUnfreezePlayerStats(); /* v1.8.19：播放结束自动清理（unfreeze = 场景播放结束，覆盖框架播放器） */
		ensureFarmState(); /* 启动兜底：存档 farm_stage 已推进但 $farm 缺失 → 补空壳，社交页不再崩 */
				mbCEPruneAveryShell();
		mbCEUiLoad(); /* v1.8.12 持久化：恢复上次页签/搜索词/折叠状态 */
		try { mbCEResumeTimers(); mbCEYanlingCheatBoot(); } catch (eY0) {} /* v2.0.0.006 言灵开关 + v2.1.18 作弊无副作用豁免：注入即补齐（钩子不落档，读档后重装） */
		/* v2.3.0 玩家的游戏：特质注册到基础 traits + 财神金钱钩子幂等补装（失败不阻断启动） */
		try { mbCEPGRegisterTrait(); mbCEPGInstallMoneyHook(); } catch (ePG0) {}
		mbCEHookErrors(); /* v1.8.12 错误收集器：window error + console.error 进面板 */
